var i=`1247-stamp-and-go-saltfish-fritters`;var a=`world-1247`;var r=`JM`;var n=`central-america-caribbean`;var o=8;var s=1483;var l={en:`Stamp and Go Saltfish Fritters`,ua:`Ямайські оладки із солоної риби`};var d={en:`Stamp and Go Saltfish Fritters is a dish from Jamaica featuring salt cod, all-purpose flour, chicken egg, green onion. This home-sized recipe records each ingredient at the step where it is used. Salt cod must be fully desalinated under refrigeration with water changes before frying the fritters.`,ua:`Ямайські оладки із солоної риби, страва кухні країни Ямайка з такими основними складниками: солона тріска, пшеничне борошно універсальне, куряче яйце, зелена цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Солону тріску потрібно вимочити в холодильнику зі змінами води перед смаженням оладок.`};var h=[{en:`Desalt the salt cod for roughly 24 hours in the refrigerator, changing the water several times, then drain; never leave soaking fish at room temperature.`,ua:`Вимочуйте солону тріску приблизно добу в холодильнику, кілька разів змінюючи воду; не залишайте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,450,`g`],[`water`,1200,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:12,i:[]},{en:`Flake the thoroughly cooked, desalted cod with a fork; remove every bone and keep the fish ready for the mixture.`,ua:`Розберіть повністю приготовану вимочену тріску виделкою на дрібні шматочки, видаліть усі кістки й залиште рибу для суміші.`,t:[`shredding`,`mixing`],m:7,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,300,`g`],[`chicken-egg`,2,`pcs`],[`green-onion`,60,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`water`,180,`ml`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 14 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 14 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:14,i:[[`canola-oil`,720,`ml`]]}];var c={slug:i,id:a,country:`JM`,region:n,servings:8,minutes:s,title:l,text:d,steps:h};export{r as country,c as default,a as id,s as minutes,n as region,o as servings,i as slug,h as steps,d as text,l as title};